#!/usr/bin/env python3
"""Summarize censored A2 evidence; no uncaptured tail/empty-counter success claims."""
from pathlib import Path
import argparse,collections,datetime,hashlib,json,re
p=argparse.ArgumentParser(description=__doc__);p.add_argument('folder',type=Path);args=p.parse_args();f=args.folder.resolve();a=json.loads((f/'analysis-a2.json').read_text());record=json.loads((f/'boot-record.json').read_text());events=[json.loads(l) for l in (f/'guard-trace.jsonl').read_text().splitlines()];chunks=[e for e in events if e.get('event')=='monitor' and e.get('length')];raw=(f/'usb.log').read_bytes();lines=raw.decode(errors='replace').splitlines();born=int(re.search(rb'^LQ101 INIT: t_ms=(\d+)',raw,re.M)[1]);memory=a['a2_memory'];valid=[s for s in a['spaces'] if s.get('rc')==0];regs=a['a2_sctlr'];cpus=sorted({int(r['cpu']) for r in regs});faults=a['faults_versus_r100b'];last=memory[-1]
