summary={'status':a['status'],'hardware_boots':1,'A3_boots':0,'image_sha256':record['image_sha256'],'log_sha256':record['log_sha256'],'trace_sha256':record['trace_sha256'],'raw_bytes':len(raw),'cooldown_seconds':record['cooldown_actual_seconds'],'monitoring_seconds':record['elapsed_seconds'],'first_data_host_s':chunks[0]['elapsed'],'last_data_host_s':chunks[-1]['elapsed'],'streamed_data_span_host_s':chunks[-1]['elapsed']-chunks[0]['elapsed'],'serial_disconnects':[e for e in events if e['event']=='serial_disconnect'],'owner_recovery':json.loads((f/'owner-recovery.json').read_text()),'returned_to_fastboot':record['returned_to_fastboot'],'guard_replay':a['exact_guard_replay'],'guard_abort':record['abort_reason'],'panic_marker':record['fatal'],'guard_limits':'No guard trigger on received evidence; silence is not healthy runtime. max_pid=0/max_si=0 are unpopulated monitor sentinels, not measured process/CPU values.','native_observer_coverage':{'memory_samples':len(memory),'last_relative_ms':int(last['relative_ms']),'valid_Data_samples':len(valid),'minimum_required_Data_samples':50,'complete_snapshots':len([s for s in a['snapshot_completeness'] if s['complete']]),'walker_begin_seen':any('stage=walker-begin' in l for l in lines),'frames':len(a['frames'])},'SCTLR':{'cpus':cpus,'missing_cpus':sorted(set(range(8))-set(cpus)),'all_observed_nTWE_zero':all(r['nTWE']=='0' for r in regs),'all_observed_nTWI_zero':all(r['nTWI']=='0' for r in regs),'rows':regs},'undefined_last_sample':undefined,'WFE_baseline_established':False,'scale_40':a['scale_effective_40_seen'],'registrations':a['registration_end_markers'],'spaces':[{'observer_ms':s['t_ms']-born,'capacity_MiB':s['blocks']*s['bsize']/1048576,'free_MiB':s['free']*s['bsize']/1048576,'raw':s['raw']} for s in valid],'memory_last_sample':{'relative_ms':int(last['relative_ms']),'free_pages':int(last['free']),'free_MiB':int(last['free'])/256},'faults':faults,'EL0_TRAP_caveat':'EL0 TRAP=0 does not mean zero faults; only capped received details classified.','received_observer_bytes':a['new_observer_log_bytes'],'received_observer_max_line_bytes':max(len(l) for l in raw.splitlines(keepends=True) if l.startswith((b'LQ101 ',b'LQ102 ',b'LIUQIN TASK_CPU'))),'missing_end_to_end_loss_counters':all(not a[k] for k in ['coverage','loss','output']),'censoring':'Capture ended by monitoring deadline after USB disappearance and owner recovery. Generic analyzer observer_lifetime_lower_ms assumes continued target execution and is not valid for this run. Empty all(...) loss fields do not establish no loss. Early block/undefined window checks cover only received windows.','next_run_authorized':False,'A3_held':True}
(f/'result-summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps({k:summary[k] for k in ['status','last_data_host_s','native_observer_coverage','WFE_baseline_established','scale_40','registrations','spaces','memory_last_sample']},indent=2))
